5309:     fn required_accepts_main_push_only_in_full_mode_and_rejects_stale_full_pr() {
5310:         let ci = valid_ci_workflow();
5311:         let run = required_body(&ci);
5312:         let base = CI_REQUIRED_BASE;
5313:         let head = CI_REQUIRED_SHA;
5314:         let push = json!({"before":base,"after":head,"ref":"refs/heads/main","repository":{"full_name":"owner/repo","id":12345}});
5315:         let full = required_decision("full", base, head, false);
5316:         let mut full = full;
5317:         full["event_name"] = json!("push");
5318:         full["run_sha"] = json!(head);
5319:         full["pr_number"] = json!(0);
5320:         let success = run_required_result(
5321:             run,
5322:             &required_results("full"),
5323:             &full,
5324:             "push",
5325:             &push,
5326:             "refs/heads/main",
5327:             &[],
5328:         );
5329:         assert!(
5330:             success.output.status.success(),
5331:             "main push full must succeed: stdout={} stderr={} calls={}",
5332:             String::from_utf8_lossy(&success.output.stdout),
5333:             String::from_utf8_lossy(&success.output.stderr),
5334:             success.calls
5335:         );
5336:         assert!(
5337:             success.calls.is_empty(),
5338:             "push must not call PR APIs: {}",
5339:             success.calls
5340:         );
5341:         assert!(
5342:             success.summary.contains("Required CI: full"),
5343:             "{}",
5344:             success.summary
5345:         );
5346: 
5347:         let event = required_pr_event(base, head, "synchronize");
5348:         let (mut live, main) = required_pr_api(base, head, "open", "synchronize");
5349:         live["head"]["sha"] = json!(CI_REQUIRED_BASE);
5350:         let live_text = live.to_string();
5351:         let main_text = main.to_string();
5352:         let replies = [
5353:             ApiReply {
5354:                 request: "api repos/owner/repo/pulls/124",
5355:                 body: live_text.into_bytes(),
5356:                 exit: 0,
5357:             },
5358:             ApiReply {
5359:                 request: "api repos/owner/repo/git/ref/heads/main",
5360:                 body: main_text.into_bytes(),
5361:                 exit: 0,
5362:             },
5363:         ];
5364:         let stale = run_required_result(
5365:             run,
5366:             &required_results("full"),
5367:             &required_decision("full", base, head, false),
5368:             "pull_request",
5369:             &event,
5370:             "refs/pull/124/merge",
5371:             &replies,
5372:         );
5373:         assert!(
5374:             !stale.output.status.success(),
5375:             "full mode must fail when final current PR SHA differs from tested SHA"
5376:         );
5377:         assert_eq!(stale.calls.lines().count(), 2, "{}", stale.calls);
5378:     }
