5727:     fn ci_mode_policy_rejects_missing_selector_wiring_and_repository_gate_ownership() {
5728:         let valid = valid_ci_workflow();
5729:         type CiMutation = (&'static str, Box<dyn Fn(&mut YamlValue)>);
5730:         let cases: Vec<CiMutation> = vec![
5731:             (
5732:                 "missing selector",
5733:                 Box::new(|ci| {
5734:                     ci["jobs"]
5735:                         .as_mapping_mut()
5736:                         .unwrap()
5737:                         .remove(YamlValue::String("classify".into()));
5738:                 }),
5739:             ),
5740:             (
5741:                 "unexpected event",
5742:                 Box::new(|ci| {
5743:                     ci["on"]["workflow_dispatch"] = yaml_serde::from_str("{}").unwrap();
5744:                 }),
5745:             ),
5746:             (
5747:                 "wrong protected checkout ref",
5748:                 Box::new(|ci| {
5749:                     ci["jobs"]["classify"]["steps"][1]["with"]["ref"] =
5750:                         YamlValue::String("github.sha".into());
5751:                 }),
5752:             ),
5753:             (
5754:                 "head helper path",
5755:                 Box::new(|ci| {
5756:                     let step = ci["jobs"]["classify"]["steps"]
5757:                         .as_sequence_mut()
5758:                         .unwrap()
5759:                         .iter_mut()
5760:                         .find(|step| step.get("id").and_then(YamlValue::as_str) == Some("decision"))
5761:                         .unwrap();
5762:                     let run = step["run"].as_str().unwrap().replace(
5763:                         "trusted-base/crates/xtask/src/ci.rs",
5764:                         "git-objects/crates/xtask/src/ci.rs",
5765:                     );
5766:                     step["run"] = YamlValue::String(run);
5767:                 }),
5768:             ),
5769:             (
5770:                 "missing common policy gate",
5771:                 Box::new(|ci| {
5772:                     ci["jobs"]["required"]["needs"]
5773:                         .as_sequence_mut()
5774:                         .unwrap()
5775:                         .retain(|need| need.as_str() != Some("repository-policy"));
5776:                 }),
5777:             ),
5778:             (
5779:                 "heavy job unconditional",
5780:                 Box::new(|ci| {
5781:                     ci["jobs"]["native"]["if"] = YamlValue::String("always()".into());
5782:                 }),
5783:             ),
5784:             (
5785:                 "decision output unbound",
5786:                 Box::new(|ci| {
5787:                     ci["jobs"]["classify"]["outputs"]["decision"] =
5788:                         YamlValue::String("${{ steps.identity.outputs.decision }}".into());
5789:                 }),
5790:             ),
5791:             (
5792:                 "required skips results",
5793:                 Box::new(|ci| {
5794:                     ci["jobs"]["required"]["steps"][0]["run"] =
5795:                         YamlValue::String("echo success".into());
5796:                 }),
5797:             ),
5798:         ];
5799:         for (label, mutate) in cases {
5800:             let mut changed = valid.clone();
5801:             mutate(&mut changed);
5802:             let issues = workflow_policy_issues_for_ci(&changed);
5803:             assert!(!issues.is_empty(), "accepted {label}");
5804:         }
5805:         let missing_release_gate = workflow_policy_issues_for_ci(&valid);
5806:         assert!(
5807:             missing_release_gate.is_empty(),
5808:             "actual consumer baseline rejected: {missing_release_gate:?}"
5809:         );
5810:         let mut without_gate = valid;
5811:         without_gate["jobs"]["repository-policy"]["steps"]
5812:             .as_sequence_mut()
5813:             .unwrap()
5814:             .retain(|step| {
5815:                 step.get("name").and_then(YamlValue::as_str)
5816:                     != Some("Check repository release policy")
5817:             });
5818:         let issues = workflow_policy_issues_for_ci(&without_gate);
5819:         assert!(
5820:             issues
5821:                 .iter()
5822:                 .any(|issue| issue.contains("repository-release-gate-missing")
5823:                     || issue.contains("repository-policy-job-invalid")),
5824:             "missing repository gate not detected: {issues:?}"
5825:         );
5826:     }
